137	                    nights INTEGER NOT NULL,
138	                    subtotal NUMERIC(10,2) NOT NULL,
139	                    discount NUMERIC(10,2) NOT NULL,
140	                    total NUMERIC(10,2) NOT NULL,
141	                    status VARCHAR(20) NOT NULL,
142	                    amount_paid NUMERIC(10,2),
143	                    refund NUMERIC(10,2),
144	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
145	                )
146	            """);
147	
148	            stmt.execute("""
149	                CREATE TABLE IF NOT EXISTS messages (
150	                    id BIGSERIAL PRIMARY KEY,
151	                    channel VARCHAR(50) NOT NULL,
152	                    "to" VARCHAR(255) NOT NULL,
153	                    subject VARCHAR(255) NOT NULL,
154	                    body TEXT NOT NULL,
155	                    status VARCHAR(20) NOT NULL,
