  1	package com.pousada.marealta.api;
  2	
  3	import com.google.gson.Gson;
  4	import com.google.gson.JsonObject;
  5	import io.javalin.http.BadRequestResponse;
  6	import io.javalin.http.Context;
  7	
  8	import java.time.LocalDate;
  9	import java.time.format.DateTimeParseException;
 10	
 11	public class Handler {
 12	    protected static final Gson gson = new Gson();
 13	
 14	    protected static void error(Context ctx, int status, String code, String message) {
 15	        JsonObject error = new JsonObject();
 16	        error.addProperty("error", code);
 17	        error.addProperty("message", message);
 18	        ctx.status(status).json(error);
 19	    }
 20	
 21	    protected static LocalDate parseDate(String dateStr) {
 22	        try {
 23	            return LocalDate.parse(dateStr);
 24	        } catch (DateTimeParseException e) {
 25	            throw new BadRequestResponse("Invalid date format: " + dateStr);
 26	        }
 27	    }
 28	
 29	    protected static String getRequiredString(JsonObject json, String field) {
 30	        if (!json.has(field) || json.get(field).isJsonNull()) {
 31	            throw new BadRequestResponse("Missing required field: " + field);
 32	        }
 33	        return json.get(field).getAsString();
 34	    }
 35	
 36	    protected static int getRequiredInt(JsonObject json, String field) {
 37	        if (!json.has(field)) {
 38	            throw new BadRequestResponse("Missing required field: " + field);
 39	        }
 40	        return json.get(field).getAsInt();
 41	    }
 42	
 43	    protected static double getRequiredDouble(JsonObject json, String field) {
 44	        if (!json.has(field)) {
 45	            throw new BadRequestResponse("Missing required field: " + field);
 46	        }
 47	        return json.get(field).getAsDouble();
 48	    }
 49	
 50	    protected static void handleException(Context ctx, Exception e) {
 51	        String message = e.getMessage();
 52	        if (message == null) {
 53	            message = e.getClass().getSimpleName();
 54	        }
 55	
 56	        if ("ROOM_NOT_FOUND".equals(message)) {
 57	            error(ctx, 404, "ROOM_NOT_FOUND", "Room not found");
 58	        } else if ("RESERVATION_NOT_FOUND".equals(message)) {
 59	            error(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
 60	        } else if ("ROOM_UNAVAILABLE".equals(message)) {
 61	            error(ctx, 409, "ROOM_UNAVAILABLE", "Room is not available for the selected dates");
 62	        } else if ("OPERATION_NOT_ALLOWED".equals(message)) {
 63	            error(ctx, 409, "OPERATION_NOT_ALLOWED", "This operation is not allowed in the current reservation state");
 64	        } else if ("CAPACITY_EXCEEDED".equals(message)) {
 65	            error(ctx, 422, "CAPACITY_EXCEEDED", "Number of guests exceeds room capacity");
 66	        } else if ("INVALID_REQUEST".equals(message)) {
 67	            error(ctx, 400, "INVALID_REQUEST", "Invalid request parameters");
 68	        } else if (e instanceof BadRequestResponse) {
 69	            error(ctx, 400, "INVALID_REQUEST", e.getMessage());
 70	        } else {
 71	            error(ctx, 500, "INTERNAL_ERROR", "Internal server error");
 72	            e.printStackTrace();
 73	        }
 74	    }
 75	}
 76	package com.pousada.marealta.api;
 77	
 78	import com.google.gson.JsonObject;
 79	import com.pousada.marealta.domain.RatePlan;
 80	import com.pousada.marealta.domain.Reservation;
 81	import com.pousada.marealta.repository.MessageRepository;
 82	import com.pousada.marealta.repository.ReservationRepository;
 83	import com.pousada.marealta.repository.RoomRepository;
 84	import com.pousada.marealta.service.ReservationService;
 85	import io.javalin.http.Context;
 86	
 87	import java.math.BigDecimal;
 88	import java.time.LocalDate;
 89	
 90	public class ReservationsHandler extends Handler {
 91	    private final ReservationService reservationService;
 92	
 93	    public ReservationsHandler(
 94	            ReservationRepository reservationRepository,
 95	            RoomRepository roomRepository,
 96	            MessageRepository messageRepository
 97	    ) {
 98	        this.reservationService = new ReservationService(
 99	            reservationRepository,
100	            roomRepository,
101	            messageRepository
102	        );
103	    }
104	
105	    public void createReservation(Context ctx) {
106	        try {
107	            JsonObject json = gson.fromJson(ctx.body(), JsonObject.class);
108	
109	            int roomNumber = getRequiredInt(json, "roomNumber");
110	            String guestName = getRequiredString(json, "guestName");
111	            String guestEmail = getRequiredString(json, "guestEmail");
112	            String guestCpf = getRequiredString(json, "guestCpf");
113	            String checkInStr = getRequiredString(json, "checkIn");
114	            String checkOutStr = getRequiredString(json, "checkOut");
115	            int guests = getRequiredInt(json, "guests");
116	            String ratePlanStr = getRequiredString(json, "ratePlan");
117	
118	            LocalDate checkIn = parseDate(checkInStr);
119	            LocalDate checkOut = parseDate(checkOutStr);
120	            RatePlan ratePlan = RatePlan.fromString(ratePlanStr);
121	
122	            Reservation reservation = reservationService.createReservation(
123	                roomNumber, guestName, guestEmail, guestCpf,
124	                checkIn, checkOut, guests, ratePlan
125	            );
126	
127	            ctx.status(201).json(reservationToJson(reservation));
128	        } catch (Exception e) {
129	            handleException(ctx, e);
130	        }
131	    }
132	
133	    public void getReservation(Context ctx) {
134	        try {
135	            long id = Long.parseLong(ctx.pathParam("id"));
136	            Reservation reservation = reservationService.getReservation(id);
137	            ctx.json(reservationToJson(reservation));
138	        } catch (Exception e) {
139	            handleException(ctx, e);
140	        }
141	    }
142	
143	    public void confirmReservation(Context ctx) {
144	        try {
145	            long id = Long.parseLong(ctx.pathParam("id"));
146	            JsonObject json = gson.fromJson(ctx.body(), JsonObject.class);
147	            BigDecimal amountPaid = new BigDecimal(json.get("amount").getAsString());
148	
149	            Reservation reservation = reservationService.confirmReservation(id, amountPaid);
150	            ctx.json(reservationToJson(reservation));
151	        } catch (Exception e) {
152	            handleException(ctx, e);
153	        }
154	    }
155	
156	    public void checkIn(Context ctx) {
157	        try {
158	            long id = Long.parseLong(ctx.pathParam("id"));
159	            Reservation reservation = reservationService.checkIn(id);
160	            ctx.json(reservationToJson(reservation));
161	        } catch (Exception e) {
162	            handleException(ctx, e);
163	        }
164	    }
165	
166	    public void checkOut(Context ctx) {
167	        try {
168	            long id = Long.parseLong(ctx.pathParam("id"));
169	            Reservation reservation = reservationService.checkOut(id);
170	
171	            String roomType = getRoomType(reservation.getRoomNumber());
172	            String comprovante = reservationService.buildComprovante(reservation, roomType);
173	
174	            JsonObject response = new JsonObject();
175	            response.addProperty("title", "Comprovante de reserva");
176	            response.addProperty("reservationId", reservation.getId());
177	            response.addProperty("guestName", reservation.getGuestName());
178	            response.addProperty("guestCpf", reservation.getGuestCpf());
179	            response.addProperty("roomNumber", reservation.getRoomNumber());
180	            response.addProperty("roomType", roomType);
181	            response.addProperty("checkIn", reservation.getCheckIn().toString());
182	            response.addProperty("checkOut", reservation.getCheckOut().toString());
183	            response.addProperty("nights", reservation.getNights());
184	            response.addProperty("subtotal", reservation.getSubtotal().doubleValue());
185	            response.addProperty("discount", reservation.getDiscount().doubleValue());
186	            response.addProperty("total", reservation.getTotal().doubleValue());
187	
188	            ctx.json(response);
189	        } catch (Exception e) {
190	            handleException(ctx, e);
191	        }
192	    }
193	
194	    public void getDocument(Context ctx) {
195	        try {
196	            long id = Long.parseLong(ctx.pathParam("id"));
197	            Reservation reservation = reservationService.getReservation(id);
198	
199	            if (reservation.getStatus().name().equals("PENDING")) {
200	                error(ctx, 409, "OPERATION_NOT_ALLOWED", "Document is not available for pending reservations");
201	                return;
202	            }
203	
204	            String roomType = getRoomType(reservation.getRoomNumber());
205	            JsonObject response = new JsonObject();
206	            response.addProperty("title", "Comprovante de reserva");
207	            response.addProperty("reservationId", reservation.getId());
208	            response.addProperty("guestName", reservation.getGuestName());
209	            response.addProperty("guestCpf", reservation.getGuestCpf());
210	            response.addProperty("roomNumber", reservation.getRoomNumber());
211	            response.addProperty("roomType", roomType);
212	            response.addProperty("checkIn", reservation.getCheckIn().toString());
213	            response.addProperty("checkOut", reservation.getCheckOut().toString());
214	            response.addProperty("nights", reservation.getNights());
215	            response.addProperty("subtotal", reservation.getSubtotal().doubleValue());
216	            response.addProperty("discount", reservation.getDiscount().doubleValue());
217	            response.addProperty("total", reservation.getTotal().doubleValue());
218	
219	            ctx.json(response);
220	        } catch (Exception e) {
221	            handleException(ctx, e);
222	        }
223	    }
224	
225	    public void cancelReservation(Context ctx) {
226	        try {
227	            long id = Long.parseLong(ctx.pathParam("id"));
228	            Reservation reservation = reservationService.cancelReservation(id);
229	            ctx.json(reservationToJson(reservation));
230	        } catch (Exception e) {
231	            handleException(ctx, e);
232	        }
233	    }
234	
235	    private JsonObject reservationToJson(Reservation reservation) {
236	        JsonObject obj = new JsonObject();
237	        obj.addProperty("id", reservation.getId());
238	        obj.addProperty("roomNumber", reservation.getRoomNumber());
239	        obj.addProperty("guestName", reservation.getGuestName());
240	        obj.addProperty("guestEmail", reservation.getGuestEmail());
241	        obj.addProperty("guestCpf", reservation.getGuestCpf());
242	        obj.addProperty("checkIn", reservation.getCheckIn().toString());
243	        obj.addProperty("checkOut", reservation.getCheckOut().toString());
244	        obj.addProperty("guests", reservation.getGuests());
245	        obj.addProperty("ratePlan", reservation.getRatePlan().getValue());
246	        obj.addProperty("nights", reservation.getNights());
247	        obj.addProperty("subtotal", reservation.getSubtotal().doubleValue());
248	        obj.addProperty("discount", reservation.getDiscount().doubleValue());
249	        obj.addProperty("total", reservation.getTotal().doubleValue());
250	        obj.addProperty("status", reservation.getStatus().name());
251	        obj.addProperty("amountPaid", reservation.getAmountPaid().doubleValue());
252	
253	        if (reservation.getRefund() != null) {
254	            obj.addProperty("refund", reservation.getRefund().doubleValue());
255	        } else {
256	            obj.add("refund", null);
257	        }
258	
259	        return obj;
260	    }
261	
262	    private String getRoomType(int roomNumber) throws Exception {
263	        return switch (roomNumber) {
264	            case 101, 102 -> "STANDARD";
265	            case 201, 202 -> "DELUXE";
266	            case 301 -> "SUITE";
267	            default -> "UNKNOWN";
268	        };
269	    }
270	}
