 10	
 11	public class Handler {
 12	    protected static final Gson gson = new Gson();
 13	
 14	    protected static void error(Context ctx, int status, String code, String message) {
 15	        JsonObject error = new JsonObject();
 16	        error.addProperty("error", code);
 17	        error.addProperty("message", message);
 18	        ctx.status(status).json(error);
 19	    }
 20	
 21	    protected static LocalDate parseDate(String dateStr) {
 22	        try {
 23	            return LocalDate.parse(dateStr);
 24	        } catch (DateTimeParseException e) {
 25	            throw new BadRequestResponse("Invalid date format: " + dateStr);
 26	        }
 27	    }
 28	
 29	    protected static String getRequiredString(JsonObject json, String field) {
 30	        if (!json.has(field) || json.get(field).isJsonNull()) {
 31	            throw new BadRequestResponse("Missing required field: " + field);
 32	        }
 33	        return json.get(field).getAsString();
 34	    }
 35	
 36	    protected static int getRequiredInt(JsonObject json, String field) {
 37	        if (!json.has(field)) {
 38	            throw new BadRequestResponse("Missing required field: " + field);
 39	        }
 40	        return json.get(field).getAsInt();
 41	    }
 42	
 43	    protected static double getRequiredDouble(JsonObject json, String field) {
 44	        if (!json.has(field)) {
 45	            throw new BadRequestResponse("Missing required field: " + field);
 46	        }
 47	        return json.get(field).getAsDouble();
 48	    }
 49	
 50	    protected static void handleException(Context ctx, Exception e) {
 51	        String message = e.getMessage();
 52	        if (message == null) {
 53	            message = e.getClass().getSimpleName();
 54	        }
 55	
 56	        if ("ROOM_NOT_FOUND".equals(message)) {
 57	            error(ctx, 404, "ROOM_NOT_FOUND", "Room not found");
 58	        } else if ("RESERVATION_NOT_FOUND".equals(message)) {
 59	            error(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
 60	        } else if ("ROOM_UNAVAILABLE".equals(message)) {
 61	            error(ctx, 409, "ROOM_UNAVAILABLE", "Room is not available for the selected dates");
 62	        } else if ("OPERATION_NOT_ALLOWED".equals(message)) {
 63	            error(ctx, 409, "OPERATION_NOT_ALLOWED", "This operation is not allowed in the current reservation state");
 64	        } else if ("CAPACITY_EXCEEDED".equals(message)) {
 65	            error(ctx, 422, "CAPACITY_EXCEEDED", "Number of guests exceeds room capacity");
 66	        } else if ("INVALID_REQUEST".equals(message)) {
 67	            error(ctx, 400, "INVALID_REQUEST", "Invalid request parameters");
 68	        } else if (e instanceof BadRequestResponse) {
 69	            error(ctx, 400, "INVALID_REQUEST", e.getMessage());
 70	        } else {
 71	            error(ctx, 500, "INTERNAL_ERROR", "Internal server error");
 72	            e.printStackTrace();
 73	        }
 74	    }
 75	}
