  2	
  3	import com.pousada.marealta.config.Config;
  4	import com.pousada.marealta.domain.MessageStatus;
  5	import com.pousada.marealta.messaging.MessageData;
  6	import com.pousada.marealta.messaging.MessageProcessorChain;
  7	import com.pousada.marealta.messaging.processors.ArchiveCopyProcessor;
  8	import com.pousada.marealta.messaging.processors.EmailValidationProcessor;
  9	import com.pousada.marealta.messaging.processors.TestModeProcessor;
 10	import com.pousada.marealta.repository.MessageRepository;
 11	
 12	public class MessageService {
 13	    private final MessageRepository messageRepository;
 14	    private final MessageProcessorChain processorChain;
 15	
 16	    public MessageService(MessageRepository messageRepository) {
 17	        this.messageRepository = messageRepository;
 18	        this.processorChain = createProcessorChain();
 19	    }
 20	
 21	    public void sendEmail(String to, String subject, String body) throws Exception {
 22	        MessageData message = new MessageData(to, subject, body);
 23	        processorChain.process(message);
 24	
 25	        messageRepository.create(
 26	            "EMAIL",
 27	            message.getTo(),
 28	            message.getSubject(),
 29	            message.getBody(),
 30	            message.getStatus()
 31	        );
 32	
 33	        if (message.shouldGenerateCopy() && !message.isBlocked()) {
 34	            messageRepository.create(
 35	                "EMAIL",
 36	                ArchiveCopyProcessor.ARCHIVE_EMAIL,
 37	                "[Cópia] " + message.getSubject(),
 38	                message.getBody(),
 39	                MessageStatus.SENT
 40	            );
 41	        }
 42	    }
 43	
 44	    private MessageProcessorChain createProcessorChain() {
 45	        MessageProcessorChain chain = new MessageProcessorChain();
 46	        chain.addProcessor(new EmailValidationProcessor(true));
 47	        chain.addProcessor(new TestModeProcessor(Config.isTestMode()));
 48	        chain.addProcessor(new ArchiveCopyProcessor(!Config.isTestMode()));
 49	        return chain;
 50	    }
 51	}
 52	package com.pousada.marealta.service;
 53	
 54	import java.math.BigDecimal;
 55	import java.math.RoundingMode;
 56	import java.time.LocalDate;
 57	import java.time.YearMonth;
 58	
 59	public class PriceCalculator {
 60	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
 61	    private static final BigDecimal DISCOUNT_RATE = new BigDecimal("0.15");
 62	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
 63	
 64	    public static BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate date) {
 65	        if (isHighSeason(date)) {
 66	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, ROUNDING_MODE);
 67	        }
 68	        return baseRate.setScale(2, ROUNDING_MODE);
 69	    }
 70	
 71	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
 72	        BigDecimal subtotal = BigDecimal.ZERO;
 73	        LocalDate current = checkIn;
 74	
 75	        while (current.isBefore(checkOut)) {
 76	            subtotal = subtotal.add(calculateNightlyPrice(baseRate, current));
 77	            current = current.plusDays(1);
 78	        }
 79	
 80	        return subtotal.setScale(2, ROUNDING_MODE);
 81	    }
 82	
 83	    public static BigDecimal calculateDiscount(BigDecimal subtotal, boolean isNonRefundable) {
 84	        if (isNonRefundable) {
 85	            return subtotal.multiply(DISCOUNT_RATE).setScale(2, ROUNDING_MODE);
 86	        }
 87	        return BigDecimal.ZERO.setScale(2, ROUNDING_MODE);
 88	    }
 89	
 90	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
 91	        return subtotal.subtract(discount).setScale(2, ROUNDING_MODE);
 92	    }
 93	
 94	    private static boolean isHighSeason(LocalDate date) {
 95	        int month = date.getMonthValue();
 96	
 97	        if (month == 7) {
 98	            return true;
 99	        }
100	
101	        if (month == 12 || month == 1 || month == 2) {
102	            return true;
103	        }
104	
105	        return false;
106	    }
107	}
