391	        if (reservation.getDiscount().signum() > 0) {
392	            sb.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
393	        }
394	
395	        sb.append("Total: ").append(formatMoney(reservation.getTotal()));
