 53	
 54	import java.math.BigDecimal;
 55	import java.math.RoundingMode;
 56	import java.time.LocalDate;
 57	import java.time.YearMonth;
 58	
 59	public class PriceCalculator {
 60	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
 61	    private static final BigDecimal DISCOUNT_RATE = new BigDecimal("0.15");
 62	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
 63	
 64	    public static BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate date) {
 65	        if (isHighSeason(date)) {
 66	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, ROUNDING_MODE);
 67	        }
 68	        return baseRate.setScale(2, ROUNDING_MODE);
 69	    }
 70	
 71	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
 72	        BigDecimal subtotal = BigDecimal.ZERO;
 73	        LocalDate current = checkIn;
 74	
 75	        while (current.isBefore(checkOut)) {
 76	            subtotal = subtotal.add(calculateNightlyPrice(baseRate, current));
 77	            current = current.plusDays(1);
 78	        }
 79	
 80	        return subtotal.setScale(2, ROUNDING_MODE);
 81	    }
 82	
 83	    public static BigDecimal calculateDiscount(BigDecimal subtotal, boolean isNonRefundable) {
 84	        if (isNonRefundable) {
 85	            return subtotal.multiply(DISCOUNT_RATE).setScale(2, ROUNDING_MODE);
 86	        }
 87	        return BigDecimal.ZERO.setScale(2, ROUNDING_MODE);
 88	    }
 89	
 90	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
 91	        return subtotal.subtract(discount).setScale(2, ROUNDING_MODE);
 92	    }
 93	
 94	    private static boolean isHighSeason(LocalDate date) {
 95	        int month = date.getMonthValue();
 96	
 97	        if (month == 7) {
 98	            return true;
 99	        }
100	
101	        if (month == 12 || month == 1 || month == 2) {
102	            return true;
103	        }
104	
105	        return false;
106	    }
107	}
