332	        return getReservation(id);
333	    }
334	
335	    public Reservation cancelReservation(long id) throws Exception {
336	        Reservation reservation = getReservation(id);
337	
338	        if (reservation.getStatus() == ReservationStatus.CHECKED_OUT ||
339	            reservation.getStatus() == ReservationStatus.CANCELLED) {
340	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
341	        }
342	
343	        BigDecimal refund = calculateRefund(reservation);
344	        reservationRepository.updateRefund(id, refund);
345	        return getReservation(id);
346	    }
347	
348	    private BigDecimal calculateRefund(Reservation reservation) {
349	        if (reservation.getStatus() == ReservationStatus.PENDING) {
350	            return BigDecimal.ZERO;
351	        }
352	
353	        if (reservation.isRefundable()) {
354	            return reservation.getAmountPaid();
355	        }
356	
357	        return BigDecimal.ZERO;
358	    }
359	
360	    private void sendConfirmationEmail(Reservation reservation, String roomType) throws Exception {
361	        String comprovante = buildComprovante(reservation, roomType);
362	
363	        String subject = "Reserva confirmada - Pousada Maré Alta";
364	        String body = String.format(
365	            "Olá, %s!\n\n" +
366	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
367	            "%s\n\n" +
368	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
369	            "Até breve!",
370	            reservation.getGuestName(),
371	            comprovante
372	        );
373	
374	        messageService.sendEmail(reservation.getGuestEmail(), subject, body);
375	    }
376	
377	    public String buildComprovante(Reservation reservation, String roomType) {
378	        String nights = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
379	
380	        StringBuilder sb = new StringBuilder();
381	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
382	        sb.append("Hóspede: ").append(reservation.getGuestName())
383	          .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
384	        sb.append("Quarto: ").append(reservation.getRoomNumber())
385	          .append(" (").append(roomType).append(")\n");
386	        sb.append("Entrada: ").append(formatDate(reservation.getCheckIn()))
387	          .append(" | Saída: ").append(formatDate(reservation.getCheckOut()))
388	          .append(" | ").append(nights).append("\n");
389	        sb.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
390	
391	        if (reservation.getDiscount().signum() > 0) {
392	            sb.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
393	        }
394	
395	        sb.append("Total: ").append(formatMoney(reservation.getTotal()));
396	
397	        return sb.toString();
398	    }
399	
400	    private String formatDate(LocalDate date) {
401	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
402	    }
403	
404	    private String formatMoney(BigDecimal value) {
405	        DecimalFormat df = new DecimalFormat("#,##0.00");
406	        DecimalFormatSymbols dfs = new DecimalFormatSymbols();
407	        dfs.setGroupingSeparator('.');
408	        dfs.setDecimalSeparator(',');
409	        df.setDecimalFormatSymbols(dfs);
410	        return "R$ " + df.format(value);
411	    }
412	
413	    private String formatCpf(String cpf) {
414	        return cpf.replaceAll("(\\d{3})(\\d{3})(\\d{3})(\\d{2})", "$1.$2.$3-$4");
415	    }
416	}

