113	import com.pousada.marealta.domain.MessageStatus;
114	
115	public class EmailValidationProcessor implements MessageProcessor {
116	    private final boolean enabled;
117	
118	    public EmailValidationProcessor(boolean enabled) {
119	        this.enabled = enabled;
120	    }
121	
122	    @Override
123	    public void process(MessageData message) {
124	        if (!enabled || message.isBlocked()) {
125	            return;
126	        }
127	
128	        if (!isValidEmail(message.getTo())) {
129	            message.setStatus(MessageStatus.BLOCKED);
130	            message.setShouldGenerateCopy(false);
131	        }
132	    }
133	
134	    private boolean isValidEmail(String email) {
135	        if (email == null || email.isEmpty()) {
136	            return false;
137	        }
138	
139	        int atIndex = email.indexOf('@');
140	        if (atIndex < 1) {
141	            return false;
142	        }
143	
144	        int lastAtIndex = email.lastIndexOf('@');
145	        if (atIndex != lastAtIndex) {
146	            return false;
147	        }
148	
149	        String afterAt = email.substring(atIndex + 1);
150	        if (afterAt.isEmpty()) {
151	            return false;
152	        }
153	
154	        int dotIndex = afterAt.indexOf('.');
155	        return dotIndex > 0 && dotIndex < afterAt.length() - 1;
156	    }
157	}
