  7	import java.sql.Connection;
  8	import java.sql.PreparedStatement;
  9	import java.sql.ResultSet;
 10	import java.sql.Statement;
 11	import java.util.ArrayList;
 12	import java.util.List;
 13	
 14	public class MessageRepository {
 15	    public long create(String channel, String to, String subject, String body, MessageStatus status) throws Exception {
 16	        Connection conn = DatabaseConnection.getConnection();
 17	        String sql = "INSERT INTO messages (channel, \"to\", subject, body, status) VALUES (?, ?, ?, ?, ?)";
 18	
 19	        try (PreparedStatement pstmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
 20	            pstmt.setString(1, channel);
 21	            pstmt.setString(2, to);
 22	            pstmt.setString(3, subject);
 23	            pstmt.setString(4, body);
 24	            pstmt.setString(5, status.name());
 25	
 26	            pstmt.executeUpdate();
 27	            ResultSet rs = pstmt.getGeneratedKeys();
 28	            if (rs.next()) {
 29	                return rs.getLong(1);
 30	            }
 31	        }
 32	        throw new Exception("Failed to create message");
 33	    }
 34	
 35	    public List<Message> getAllMessages() throws Exception {
 36	        List<Message> messages = new ArrayList<>();
 37	        Connection conn = DatabaseConnection.getConnection();
 38	        try (Statement stmt = conn.createStatement()) {
 39	            ResultSet rs = stmt.executeQuery("SELECT id, channel, \"to\", subject, body, status FROM messages ORDER BY id");
 40	            while (rs.next()) {
 41	                messages.add(new Message(
 42	                    rs.getLong("id"),
 43	                    rs.getString("channel"),
 44	                    rs.getString("to"),
 45	                    rs.getString("subject"),
 46	                    rs.getString("body"),
 47	                    MessageStatus.fromString(rs.getString("status"))
 48	                ));
 49	            }
 50	        }
 51	        return messages;
 52	    }
 53	}
