 69	import java.util.List;
 70	
 71	public class ReservationRepository {
 72	    public long create(
 73	            int roomNumber,
 74	            String guestName,
 75	            String guestEmail,
 76	            String guestCpf,
 77	            LocalDate checkIn,
 78	            LocalDate checkOut,
 79	            int guests,
 80	            RatePlan ratePlan,
 81	            int nights,
 82	            BigDecimal subtotal,
 83	            BigDecimal discount,
 84	            BigDecimal total
 85	    ) throws Exception {
 86	        Connection conn = DatabaseConnection.getConnection();
 87	        String sql = """
 88	            INSERT INTO reservations (
 89	                room_number, guest_name, guest_email, guest_cpf,
 90	                check_in, check_out, guests, rate_plan, nights,
 91	                subtotal, discount, total, status, amount_paid
 92	            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
 93	        """;
 94	
 95	        try (PreparedStatement pstmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
 96	            pstmt.setInt(1, roomNumber);
 97	            pstmt.setString(2, guestName);
 98	            pstmt.setString(3, guestEmail);
 99	            pstmt.setString(4, guestCpf);
100	            pstmt.setDate(5, Date.valueOf(checkIn));
101	            pstmt.setDate(6, Date.valueOf(checkOut));
102	            pstmt.setInt(7, guests);
103	            pstmt.setString(8, ratePlan.getValue());
104	            pstmt.setInt(9, nights);
105	            pstmt.setBigDecimal(10, subtotal);
106	            pstmt.setBigDecimal(11, discount);
107	            pstmt.setBigDecimal(12, total);
108	            pstmt.setString(13, ReservationStatus.PENDING.name());
109	            pstmt.setBigDecimal(14, BigDecimal.ZERO);
110	
111	            pstmt.executeUpdate();
112	            ResultSet rs = pstmt.getGeneratedKeys();
113	            if (rs.next()) {
114	                return rs.getLong(1);
115	            }
116	        }
117	        throw new Exception("Failed to create reservation");
118	    }
119	
120	    public Reservation getById(long id) throws Exception {
121	        Connection conn = DatabaseConnection.getConnection();
122	        String sql = "SELECT * FROM reservations WHERE id = ?";
123	
124	        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
125	            pstmt.setLong(1, id);
126	            ResultSet rs = pstmt.executeQuery();
127	
128	            if (rs.next()) {
129	                return mapResultSetToReservation(rs);
130	            }
131	        }
132	        return null;
133	    }
134	
135	    public void updateStatus(long id, ReservationStatus status) throws Exception {
136	        Connection conn = DatabaseConnection.getConnection();
137	        String sql = "UPDATE reservations SET status = ? WHERE id = ?";
138	
139	        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
140	            pstmt.setString(1, status.name());
141	            pstmt.setLong(2, id);
142	            pstmt.executeUpdate();
143	        }
144	    }
145	
146	    public void updateAmountPaid(long id, BigDecimal amountPaid) throws Exception {
147	        Connection conn = DatabaseConnection.getConnection();
148	        String sql = "UPDATE reservations SET amount_paid = ?, status = ? WHERE id = ?";
149	
150	        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
151	            pstmt.setBigDecimal(1, amountPaid);
152	            pstmt.setString(2, ReservationStatus.CONFIRMED.name());
153	            pstmt.setLong(3, id);
154	            pstmt.executeUpdate();
155	        }
156	    }
157	
158	    public void updateRefund(long id, BigDecimal refund) throws Exception {
159	        Connection conn = DatabaseConnection.getConnection();
160	        String sql = "UPDATE reservations SET refund = ?, status = ? WHERE id = ?";
161	
162	        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
163	            pstmt.setBigDecimal(1, refund);
164	            pstmt.setString(2, ReservationStatus.CANCELLED.name());
165	            pstmt.setLong(3, id);
166	            pstmt.executeUpdate();
167	        }
168	    }
169	
170	    public List<Reservation> getReservationsByRoomAndDate(int roomNumber, LocalDate date) throws Exception {
171	        Connection conn = DatabaseConnection.getConnection();
172	        String sql = """
173	            SELECT * FROM reservations
174	            WHERE room_number = ?
175	            AND check_in <= ?
176	            AND check_out > ?
177	            AND status != 'CANCELLED'
178	        """;
179	
180	        List<Reservation> reservations = new ArrayList<>();
181	        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
182	            pstmt.setInt(1, roomNumber);
183	            pstmt.setDate(2, Date.valueOf(date));
184	            pstmt.setDate(3, Date.valueOf(date));
185	
186	            ResultSet rs = pstmt.executeQuery();
187	            while (rs.next()) {
188	                reservations.add(mapResultSetToReservation(rs));
189	            }
190	        }
191	        return reservations;
192	    }
193	
194	    public List<Reservation> getReservationsByMonthAndStatus(int year, int month) throws Exception {
195	        Connection conn = DatabaseConnection.getConnection();
196	        String sql = """
197	            SELECT * FROM reservations
198	            WHERE EXTRACT(YEAR FROM check_in) = ?
199	            AND EXTRACT(MONTH FROM check_in) = ?
200	            AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT', 'CANCELLED')
201	            AND amount_paid > 0
202	            ORDER BY check_in, id
203	        """;
204	
205	        List<Reservation> reservations = new ArrayList<>();
206	        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
207	            pstmt.setInt(1, year);
208	            pstmt.setInt(2, month);
209	
210	            ResultSet rs = pstmt.executeQuery();
211	            while (rs.next()) {
212	                reservations.add(mapResultSetToReservation(rs));
213	            }
214	        }
215	        return reservations;
216	    }
217	
218	    public List<Reservation> getConfirmedReservationsByDate(LocalDate date) throws Exception {
219	        Connection conn = DatabaseConnection.getConnection();
220	        String sql = """
221	            SELECT * FROM reservations
222	            WHERE (status = 'CONFIRMED' OR status = 'CHECKED_IN' OR status = 'CHECKED_OUT')
223	            AND check_in <= ?
224	            AND check_out > ?
225	            ORDER BY room_number
226	        """;
227	
228	        List<Reservation> reservations = new ArrayList<>();
229	        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
230	            pstmt.setDate(1, Date.valueOf(date));
231	            pstmt.setDate(2, Date.valueOf(date));
232	
233	            ResultSet rs = pstmt.executeQuery();
234	            while (rs.next()) {
235	                reservations.add(mapResultSetToReservation(rs));
236	            }
237	        }
