  3	import com.pousada.marealta.domain.MessageStatus;
  4	import com.pousada.marealta.messaging.processors.EmailValidationProcessor;
  5	import com.pousada.marealta.messaging.processors.TestModeProcessor;
  6	import org.junit.Assert;
  7	import org.junit.Test;
  8	
  9	public class MessageProcessorChainTest {
 10	    @Test
 11	    public void testInvalidEmailBlocked() {
 12	        MessageProcessorChain chain = new MessageProcessorChain();
 13	        chain.addProcessor(new EmailValidationProcessor(true));
 14	
 15	        MessageData message = new MessageData("invalid-email", "Subject", "Body");
 16	        chain.process(message);
 17	
 18	        Assert.assertEquals(MessageStatus.BLOCKED, message.getStatus());
 19	    }
 20	
 21	    @Test
 22	    public void testValidEmailAllowed() {
 23	        MessageProcessorChain chain = new MessageProcessorChain();
 24	        chain.addProcessor(new EmailValidationProcessor(true));
 25	
 26	        MessageData message = new MessageData("user@example.com", "Subject", "Body");
 27	        chain.process(message);
 28	
 29	        Assert.assertEquals(MessageStatus.SENT, message.getStatus());
 30	    }
 31	
 32	    @Test
 33	    public void testTestModeRedirection() {
 34	        MessageProcessorChain chain = new MessageProcessorChain();
 35	        chain.addProcessor(new EmailValidationProcessor(true));
 36	        chain.addProcessor(new TestModeProcessor(true));
 37	
 38	        MessageData message = new MessageData("user@example.com", "Confirmação", "Seu pedido");
 39	        chain.process(message);
 40	
 41	        Assert.assertEquals("testes@pousadamarealta.com.br", message.getTo());
 42	        Assert.assertTrue(message.getSubject().startsWith("[TESTE]"));
 43	        Assert.assertTrue(message.getBody().contains("Destinatário original: user@example.com"));
 44	        Assert.assertFalse(message.shouldGenerateCopy());
 45	    }
 46	
 47	    @Test
 48	    public void testBlockedMessageDoesNotProcessFurther() {
 49	        MessageProcessorChain chain = new MessageProcessorChain();
 50	        chain.addProcessor(new EmailValidationProcessor(true));
 51	        chain.addProcessor(new TestModeProcessor(true));
 52	
 53	        MessageData message = new MessageData("invalid@email", "Subject", "Body");
 54	        chain.process(message);
 55	
 56	        Assert.assertEquals(MessageStatus.BLOCKED, message.getStatus());
 57	        Assert.assertEquals("invalid@email", message.getTo());
 58	        Assert.assertFalse(message.getSubject().startsWith("[TESTE]"));
 59	    }
 60	}
